/* ---- BGS chapter 4 widgets: topography and climate of Bangladesh ---- */
const { B, SRC, CAT, chips, chipHtml, card, list, tiles, bars, legend, flow, stepper, worldMap, bdMap, sasiaMap, halo } = window.G;
const SCHEM = () => L2("Schematic: whole districts are coloured because the textbook names districts. Real boundaries of these regions do not follow district borders.", "নকশা-মানচিত্র: বইয়ে জেলার নাম দেওয়া আছে বলে পুরো জেলা রং করা হয়েছে। এসব অঞ্চলের আসল সীমা জেলার সীমানা মেনে চলে না।");
const dn = d => L2(d.k, d.bn);

/* 4.1.1 where Bangladesh is, and what lies on each side */
W.g4loc = (el) => {
  el.innerHTML = chipHtml("g4l-m", [["bd", L2("Bangladesh and its neighbours", "বাংলাদেশ ও প্রতিবেশী")], ["as", L2("In South Asia", "দক্ষিণ এশিয়ায়")], ["div", L2("8 divisions", "৮টি বিভাগ")]], "bd") + `<div class="g4l-map" style="margin-top:8px"></div><div class="g-card" id="g4l-c" style="margin-top:8px"></div><div class="g-src" id="g4l-s"></div>`;
  const box = $(".g4l-map", el), cardEl = $("#g4l-c", el);
  const facts = () => tiles([[L2("1,47,570 km²", "১,৪৭,৫৭০ বর্গ কিমি"), L2("total area (56,977 sq. miles)", "মোট আয়তন (৫৬,৯৭৭ বর্গমাইল)")], [L2("440 km", "৪৪০ কিমি"), L2("greatest east–west extent", "পূর্ব-পশ্চিমে সর্বোচ্চ বিস্তৃতি")], [L2("760 km", "৭৬০ কিমি"), L2("greatest NNW–SSE extent", "উত্তর-উত্তর পশ্চিম থেকে দক্ষিণ-দক্ষিণ পূর্বে")]]);
  const show = k => {
    box.className = "g4l-map"; $("#g4l-s", el).textContent = k === "as" ? SRC.sasia() : SRC.bd();
    if (k === "as") sasiaMap(box, { countries: { BGD: "var(--c)" }, labels: ["IND", "MMR", "NPL", "BTN", "CHN", "PAK", "LKA"] }).then(m => {
      m.draw(`<line x1="0" x2="${m.d.w}" y1="${m.Y(23.5)}" y2="${m.Y(23.5)}" stroke="var(--bad)" stroke-dasharray="5 4"/><text x="4" y="${m.Y(23.5) - 4}" font-size="12" fill="var(--bad)">${L2("Tropic of Cancer", "কর্কটক্রান্তি রেখা")}</text><text x="${m.X(90.3)}" y="${m.Y(24.6)}" font-size="12" font-weight="700" text-anchor="middle" fill="var(--ink)" ${halo}>${L2("Bangladesh", "বাংলাদেশ")}</text>`);
      cardEl.innerHTML = `<p>${L2("Bangladesh lies in the south of the continent of Asia, at the head of the Bay of Bengal, in the basin of three great rivers: the Ganges, the Brahmaputra and the Meghna.", "বাংলাদেশ এশিয়া মহাদেশের দক্ষিণে, বঙ্গোপসাগরের উত্তর প্রান্তে, গঙ্গা, ব্রহ্মপুত্র ও মেঘনা এই তিন বড় নদীর অববাহিকায় অবস্থিত।")}</p>`;
    }).catch(() => {});
    else if (k === "div") bdMap(box, { divLabels: true, nbLabels: false, fill: d => ({ fill: CAT[["Barishal", "Chattogram", "Dhaka", "Khulna", "Mymensingh", "Rajshahi", "Rangpur", "Sylhet"].indexOf(d.dv)], op: .5 }), tap: (d, m) => { if (!d.k) return; m.outline(d.k); cardEl.innerHTML = `<p><b>${dn(d)}</b> ${L2("district, ", "জেলা, ")}${L2(d.dv, m.d.divisions.find(v => v.k === d.dv).bn)} ${L2("division", "বিভাগ")}</p>`; } }).then(() => {
      cardEl.innerHTML = `<p>${L2("Bangladesh has 8 divisions and 64 districts. Tap a district for its name; use + to zoom in until the district names appear.", "বাংলাদেশে ৮টি বিভাগ ও ৬৪টি জেলা। নাম দেখতে জেলায় চাপ দাও; + চেপে বড় করলে জেলার নাম দেখা যাবে।")}</p>`;
    }).catch(() => {});
    else bdMap(box, { lines: true, fill: () => ({ fill: "var(--c)", op: .28 }) }).then(m => {
      const x0 = m.X(88.017), x1 = m.X(92.683), y0 = m.Y(26.633), y1 = m.Y(20.567);
      m.draw(`<rect x="${x0}" y="${y0}" width="${x1 - x0}" height="${y1 - y0}" fill="none" stroke="var(--ink)" stroke-width="1" stroke-dasharray="3 3"/>
        <g font-size="12" fill="var(--ink)" font-weight="600"><text x="${(x0 + x1) / 2}" y="${y0 - 4}" text-anchor="middle" ${halo}>${L2("26°38′ N", "২৬°৩৮′ উ")}</text><text x="${(x0 + x1) / 2}" y="${y1 + 12}" text-anchor="middle" ${halo}>${L2("20°34′ N", "২০°৩৪′ উ")}</text>
        <text x="${x0 + 3}" y="${m.Y(22.2)}" ${halo}>${L2("88°01′ E", "৮৮°০১′ পূ")}</text><text x="${x1 - 3}" y="${m.Y(24.9)}" text-anchor="end" ${halo}>${L2("92°41′ E", "৯২°৪১′ পূ")}</text></g>`);
      cardEl.innerHTML = facts() + list(L2(["<b>North:</b> West Bengal, Meghalaya and Assam (India)", "<b>East:</b> Assam, Tripura and Mizoram (India), and Myanmar", "<b>South:</b> the Bay of Bengal", "<b>West:</b> West Bengal (India)", "The Tropic of Cancer (23.5° N) passes through the middle of the country"], ["<b>উত্তরে:</b> ভারতের পশ্চিমবঙ্গ, মেঘালয় ও আসাম", "<b>পূর্বে:</b> ভারতের আসাম, ত্রিপুরা ও মিজোরাম, এবং মিয়ানমার", "<b>দক্ষিণে:</b> বঙ্গোপসাগর", "<b>পশ্চিমে:</b> ভারতের পশ্চিমবঙ্গ", "দেশের মাঝামাঝি দিয়ে কর্কটক্রান্তি রেখা (২৩.৫° উ) গেছে"]));
    }).catch(() => {});
  };
  chips(el, ".g4l-m", show); show("bd");
};

/* 4.1.2 the three physiographic regions, by the districts the textbook lists */
const HILL_SE = ["Rangamati", "Bandarban", "Khagrachhari", "Cox's Bazar"], HILL_SE_P = ["Chattogram"], HILL_N = ["Mymensingh", "Netrokona", "Sylhet", "Moulvibazar", "Habiganj"];
const BARIND = ["Naogaon", "Rajshahi", "Bogura", "Joypurhat", "Rangpur", "Dinajpur"], MADHU = ["Mymensingh", "Tangail", "Gazipur", "Dhaka"], LALMAI = ["Cumilla"];
W.g4land = (el) => {
  const C = { hill: CAT[0], ter: CAT[1], plain: CAT[2] };
  const INFO = {
    all: [L2("Three kinds of land", "তিন রকম ভূমি"), `<div style="display:flex;height:22px;border-radius:8px;overflow:hidden;margin:2px 0 8px;font-size:12px;color:#fff;text-align:center;line-height:22px"><span style="width:12%;background:${C.hill}">${B(12)}%</span><span style="width:8%;background:${C.ter}">${B(8)}%</span><span style="flex:1;background:${C.plain}">${B(80)}%</span></div>` + list(L2(["<b>Hills of the Tertiary age</b>: about 12% of the land", "<b>Terraces of the Pleistocene age</b>: about 8%", "<b>Floodplain of recent times</b>: about 80%", "The land slopes gently from north to south, so the rivers flow south into the Bay of Bengal"], ["<b>টারশিয়ারি যুগের পাহাড়</b>: মোট ভূমির প্রায় ১২%", "<b>প্লাইস্টোসিন কালের সোপান</b>: প্রায় ৮%", "<b>সাম্প্রতিক কালের প্লাবন সমভূমি</b>: প্রায় ৮০%", "ভূমি উত্তর থেকে দক্ষিণে ক্রমশ ঢালু, তাই নদীগুলো দক্ষিণে বঙ্গোপসাগরের দিকে বয়ে গেছে"]))],
    hill: [L2("Hills of the Tertiary age (about 12%)", "টারশিয়ারি যুগের পাহাড়সমূহ (প্রায় ১২%)"), list(L2(["Formed when the Himalayas were rising in the Tertiary age", "<b>South-eastern hills:</b> Rangamati, Bandarban, Khagrachhari, Cox's Bazar and the east of Chattogram; average height 610 m; made of sandstone, shale and clay", "Highest peak in the textbook: Tajingdong (Bijoy), 1,231 m, in Bandarban; second: Keokradong, 1,230 m; also Modok Mual (1,000 m) and Pyramid (915 m)", "<b>Northern and north-eastern hills:</b> north of Mymensingh and Netrokona, north and north-east of Sylhet, south of Moulvibazar and Habiganj; not more than 244 m high", "The low northern hills (30 to 90 m) are called <i>tila</i>; Chiknagul, Khasia and Jaintia are the main ones"], ["টারশিয়ারি যুগে হিমালয় পর্বত উত্থিত হওয়ার সময় সৃষ্টি", "<b>দক্ষিণ-পূর্বাঞ্চলের পাহাড়:</b> রাঙ্গামাটি, বান্দরবান, খাগড়াছড়ি, কক্সবাজার ও চট্টগ্রামের পূর্বাংশ; গড় উচ্চতা ৬১০ মিটার; বেলে পাথর, শেল ও কর্দম দিয়ে গঠিত", "বইয়ে সর্বোচ্চ শৃঙ্গ: তাজিংডং (বিজয়), ১,২৩১ মিটার, বান্দরবানে; দ্বিতীয়: কিওক্রাডং, ১,২৩০ মিটার; আরও আছে মোদকমুয়াল (১,০০০ মি) ও পিরামিড (৯১৫ মি)", "<b>উত্তর ও উত্তর-পূর্বাঞ্চলের পাহাড়:</b> ময়মনসিংহ ও নেত্রকোনার উত্তরাংশ, সিলেটের উত্তর ও উত্তর-পূর্বাংশ, মৌলভীবাজার ও হবিগঞ্জের দক্ষিণাংশ; উচ্চতা ২৪৪ মিটারের বেশি নয়", "উত্তরের নিচু পাহাড়গুলো (৩০-৯০ মি) স্থানীয়ভাবে টিলা; চিকনাগুল, খাসিয়া ও জয়ন্তিয়া প্রধান"]))],
    ter: [L2("Terraces of the Pleistocene age (about 8%)", "প্লাইস্টোসিন কালের সোপানসমূহ (প্রায় ৮%)"), list(L2(["Raised land thought to have been built by floods of melting ice water about 25,000 years ago", "<b>Barind tract:</b> parts of Naogaon, Rajshahi, Bogura, Joypurhat, Rangpur and Dinajpur; 9,320 km²; 6 to 12 m above the floodplain; grey and red soil", "<b>Madhupur and Bhawal tract:</b> parts of Mymensingh, Tangail, Gazipur and Dhaka; about 4,103 km²; 6 to 30 m above the plain; reddish and grey soil", "<b>Lalmai hills:</b> from Lalmai, 8 km west of Cumilla town, to Mainamati; 34 km²; average height 21 m; reddish soil with pebbles, sand and gravel"], ["আনুমানিক ২৫,০০০ বছর আগে বরফ গলা পানির প্লাবনে গঠিত বলে ধারণা করা হয়", "<b>বরেন্দ্রভূমি:</b> নওগাঁ, রাজশাহী, বগুড়া, জয়পুরহাট, রংপুর ও দিনাজপুরের অংশবিশেষ; ৯,৩২০ বর্গ কিমি; প্লাবন সমভূমি থেকে ৬-১২ মিটার উঁচু; মাটি ধূসর ও লাল", "<b>মধুপুর ও ভাওয়ালের গড়:</b> ময়মনসিংহ, টাঙ্গাইল, গাজীপুর ও ঢাকার অংশবিশেষ; প্রায় ৪,১০৩ বর্গ কিমি; সমভূমি থেকে ৬-৩০ মিটার উঁচু; মাটি লালচে ও ধূসর", "<b>লালমাই পাহাড়:</b> কুমিল্লা শহরের ৮ কিমি পশ্চিমে লালমাই থেকে ময়নামতি পর্যন্ত; ৩৪ বর্গ কিমি; গড় উচ্চতা ২১ মিটার; লালচে মাটি, নুড়ি-বালি-কাঁকর মেশানো"]))],
    plain: [L2("Floodplain of recent times (about 80%)", "সাম্প্রতিক কালের প্লাবন সমভূমি (প্রায় ৮০%)"), list(L2(["A vast plain of about 1,24,266 km², built layer by layer from the silt that river floods leave every rainy season", "The soil is very deep and very fertile, so most farming is done here", "Parts of it: the Himalayan piedmont plain (most of Rangpur and Dinajpur), the river floodplains, the Sylhet basin, the <b>delta plain</b> (Faridpur, Kushtia, Jashore, Khulna, Barishal, Patuakhali), the <b>coastal plain</b> (Noakhali and the lower Feni river to Cox's Bazar) and the <b>tidal plain</b> (Khulna, Patuakhali and part of Barguna)"], ["প্রায় ১,২৪,২৬৬ বর্গ কিমির বিশাল সমভূমি; প্রতি বর্ষায় নদীর বন্যায় আসা পলি বছরের পর বছর জমে গঠিত", "মাটির স্তর খুব গভীর এবং ভূমি খুব উর্বর, তাই কৃষির বেশির ভাগই এখানে", "এর ভাগ: হিমালয়ের পাদদেশীয় সমভূমি (রংপুর ও দিনাজপুরের অধিকাংশ), নদীর প্লাবন সমভূমি, সিলেট অববাহিকা, <b>ব-দ্বীপ সমভূমি</b> (ফরিদপুর, কুষ্টিয়া, যশোর, খুলনা, বরিশাল, পটুয়াখালী), <b>উপকূলীয় সমভূমি</b> (নোয়াখালী ও ফেনী নদীর নিম্নভাগ থেকে কক্সবাজার) এবং <b>স্রোতজ সমভূমি</b> (খুলনা, পটুয়াখালী ও বরগুনার অংশ)"]))]
  };
  el.innerHTML = chipHtml("g4d-m", [["all", L2("All three", "তিনটিই")], ["hill", L2("Hills", "পাহাড়")], ["ter", L2("Terraces", "সোপান")], ["plain", L2("Floodplain", "প্লাবন সমভূমি")]], "all") + `<div class="g4d-map" style="margin-top:8px"></div>` + legend([[C.hill, L2("hills", "পাহাড়"), .75], [C.ter, L2("terraces", "সোপান"), .75], [C.plain, L2("floodplain", "প্লাবন সমভূমি"), .5]]) + `<div class="g-card" id="g4d-c" style="margin-top:8px"></div><div class="g-src">${SCHEM()} ${SRC.bd()}</div>`;
  let mode = "all";
  const cls = k => ({ hill: HILL_SE.includes(k) ? 2 : (HILL_SE_P.includes(k) || HILL_N.includes(k)) ? 1 : 0, ter: (BARIND.includes(k) || MADHU.includes(k) || LALMAI.includes(k)) ? 1 : 0 });
  bdMap($(".g4d-map", el), { nbLabels: false, tap: (d, m) => {
    if (!d.k) return; m.outline(d.k); const c = cls(d.k), parts = [];
    if (HILL_SE.includes(d.k) || HILL_SE_P.includes(d.k)) parts.push(L2("south-eastern Tertiary hills" + (HILL_SE_P.includes(d.k) ? " (eastern part)" : ""), "দক্ষিণ-পূর্বাঞ্চলের টারশিয়ারি পাহাড়" + (HILL_SE_P.includes(d.k) ? " (পূর্বাংশ)" : "")));
    if (HILL_N.includes(d.k)) parts.push(L2("northern / north-eastern hills (part of the district)", "উত্তর / উত্তর-পূর্বাঞ্চলের পাহাড় (জেলার অংশবিশেষ)"));
    if (BARIND.includes(d.k)) parts.push(L2("Barind tract (part)", "বরেন্দ্রভূমি (অংশবিশেষ)")); if (MADHU.includes(d.k)) parts.push(L2("Madhupur and Bhawal tract (part)", "মধুপুর ও ভাওয়ালের গড় (অংশবিশেষ)")); if (LALMAI.includes(d.k)) parts.push(L2("Lalmai hills (a small area)", "লালমাই পাহাড় (ছোট এলাকা)"));
    if (!HILL_SE.includes(d.k)) parts.push(L2("recent floodplain", "সাম্প্রতিক কালের প্লাবন সমভূমি"));
    $("#g4d-c", el).innerHTML = card(dn(d), list(parts));
  } }).then(m => {
    const paint = () => {
      m.paint(d => { const c = cls(d.k);
        if (mode === "hill") return c.hill ? { fill: C.hill, op: c.hill === 2 ? .8 : .4 } : null;
        if (mode === "ter") return c.ter ? { fill: C.ter, op: .7 } : null;
        if (mode === "plain") return c.hill === 2 ? null : { fill: C.plain, op: (c.hill || c.ter) ? .25 : .5 };
        return c.hill === 2 ? { fill: C.hill, op: .8 } : c.ter ? { fill: C.ter, op: .7 } : c.hill ? { fill: C.hill, op: .4 } : { fill: C.plain, op: .45 }; });
      m.marks(mode === "plain" ? [] : [...(mode !== "ter" ? [{ place: "ruma", label: L2("highest peaks", "সর্বোচ্চ শৃঙ্গ"), col: "var(--ink)", anchor: "end", dx: -6 }, { place: "jaintiapur", label: L2("tila (hillocks)", "টিলা"), col: "var(--ink)", anchor: "end", dx: -6, dy: -5 }] : []), ...(mode !== "hill" ? [{ place: "naogaon", label: L2("Barind", "বরেন্দ্রভূমি"), col: "var(--ink)", dy: -6 }, { place: "madhupur", label: L2("Madhupur", "মধুপুর গড়"), col: "var(--ink)" }, { place: "lalmai", label: L2("Lalmai", "লালমাই"), col: "var(--ink)" }] : [])]);
      $("#g4d-c", el).innerHTML = card(INFO[mode][0], INFO[mode][1]); m.outline(null);
    };
    chips(el, ".g4d-m", k => { mode = k; paint(); }); paint();
  }).catch(() => {});
};

/* 4.1.3 where people are few and where they are many */
W.g4pop = (el) => {
  const SPARSE = ["Rangamati", "Bandarban", "Khagrachhari"], SUND = ["Satkhira", "Khulna", "Bagerhat"];
  el.innerHTML = tiles([[L2("16.98 crore", "১৬.৯৮ কোটি"), L2("people (Census 2022)", "জনসংখ্যা (জনশুমারি ২০২২)")], [L2("1.12%", "১.১২%"), L2("growth each year", "বার্ষিক বৃদ্ধির হার")], [L2("1,119", "১,১১৯"), L2("people per km²", "জন, প্রতি বর্গ কিমিতে")], [L2("8th", "৮ম"), L2("in the world by population", "জনসংখ্যায় বিশ্বে স্থান")]]) + `<div class="g4p-map" style="margin-top:8px"></div>` + legend([[CAT[3], L2("thinly peopled", "জনবিরল"), .7], ["var(--bad)", L2("industrial towns named in the book", "বইয়ে উল্লিখিত শিল্প শহর")], [CAT[2], L2("fertile river plains: dense", "উর্বর নদী-সমভূমি: ঘনবসতি"), .4]]) + `<div class="g-card" id="g4p-c" style="margin-top:8px"></div><div class="g-src">${SCHEM()} ${SRC.bd()}</div>`;
  const T = {
    sparse: [L2("Hill tracts: few people", "পার্বত্য এলাকা: জনবসতি কম"), L2(["Earning a living on steep, forested hills is hard", "Few good roads and no railway", "Much of the land is forest"], ["খাড়া, বনে ঢাকা পাহাড়ে জীবিকা নির্বাহ কষ্টকর", "ভালো রাস্তাঘাট কম, রেল সংযোগ নেই", "জমির বড় অংশ বনভূমি"])],
    sund: [L2("The Sundarbans area: few people", "সুন্দরবন অঞ্চল: জনবসতি কম"), L2(["The south of these districts is mangrove forest, cut by tidal rivers", "Earning a living there is hard and communication is poor"], ["এই জেলাগুলোর দক্ষিণাংশ জোয়ার-ভাটার নদীতে ঘেরা ম্যানগ্রোভ বন", "সেখানে জীবিকা নির্বাহ কষ্টকর, যাতায়াতও অনুন্নত"])],
    plain: [L2("River plains: many people", "নদী-সমভূমি: ঘন জনবসতি"), L2(["Fertile silt makes farming easy", "Navigable rivers, roads and railways make travel and trade easy", "A mild climate that suits crops", "Schools, colleges and cultural life also draw people"], ["উর্বর পলিমাটিতে কৃষিকাজ সহজ", "নাব্য নদী, সড়ক ও রেলপথে যাতায়াত ও ব্যবসা সহজ", "কৃষির অনুকূল সমভাবাপন্ন জলবায়ু", "শিক্ষা ও সংস্কৃতির সুযোগও মানুষকে টানে"])],
    ind: [L2("Industrial towns: very dense", "শিল্প শহর: খুব ঘন বসতি"), L2(["Workers gather where there are mills, factories and mineral resources", "Around the main industry many smaller industries and trade grow up", "The book names Tejgaon, Tongi, Narsingdi, Khulna and Chattogram"], ["কলকারখানা ও খনিজ সম্পদ যেখানে, সেখানে জীবিকার সন্ধানে শ্রমিকরা জড়ো হয়", "প্রধান শিল্পকে ঘিরে অনেক আনুষঙ্গিক শিল্প ও ব্যবসা গড়ে ওঠে", "বইয়ে তেজগাঁও, টঙ্গী, নরসিংদী, খুলনা ও চট্টগ্রামের নাম আছে"])] };
  const show = k => $("#g4p-c", el).innerHTML = card(T[k][0], list(T[k][1]));
  bdMap($(".g4p-map", el), { nbLabels: false, fill: d => SPARSE.includes(d.k) ? { fill: CAT[3], op: .7 } : SUND.includes(d.k) ? { fill: CAT[3], op: .35 } : { fill: CAT[2], op: .35 },
    tap: (d, m) => { if (d.mark) return show("ind"); m.outline(d.k); show(SPARSE.includes(d.k) ? "sparse" : SUND.includes(d.k) ? "sund" : "plain"); } }).then(m => {
    m.marks([{ place: "dhaka", k: "i1", label: L2("Tejgaon (Dhaka)", "তেজগাঁও (ঢাকা)"), col: "var(--bad)", anchor: "end", dx: -6, dy: 9 }, { place: "tongi", k: "i2", label: L2("Tongi", "টঙ্গী"), col: "var(--bad)", dy: -5 }, { place: "narsingdi", k: "i3", label: L2("Narsingdi", "নরসিংদী"), col: "var(--bad)" }, { place: "khulna", k: "i4", label: L2("Khulna", "খুলনা"), col: "var(--bad)" }, { place: "chattogram", k: "i5", label: L2("Chattogram", "চট্টগ্রাম"), col: "var(--bad)", anchor: "end", dx: -6 }]);
    $("#g4p-c", el).innerHTML = `<p>${L2("People live almost everywhere in Bangladesh, but not evenly. Tap a blue district, a green district or a red town to see why.", "বাংলাদেশের প্রায় সব জায়গায় মানুষ বাস করে, তবে সমানভাবে নয়। কারণ জানতে নীল জেলা, সবুজ জেলা বা লাল শহরে চাপ দাও।")}</p>`;
  }).catch(() => {});
};

/* 4.1.4 more people, less land */
W.g4landuse = (el) => {
  el.innerHTML = `<div class="g-card" style="margin-bottom:10px"><h4>${L2("Land per person", "মাথাপিছু জমি")}</h4>${`<div class="g-bars">${[[L2("1974", "১৯৭৪"), .28], [L2("now", "বর্তমানে"), .25]].map(([t, v]) => `<div class="row"><span>${t}</span><span class="trk"><i style="width:${v / .28 * 100}%"></i></span><span class="val">${B(v.toFixed(2))} ${L2("acre", "একর")}</span></div>`).join("")}</div>`}<p style="margin-top:8px">${L2("A family that had 100 bighas of land 30 years ago may now have 10 bighas or less.", "৩০ বছর আগে যে পরিবারের ১০০ বিঘা জমি ছিল, এখন তার আছে ১০ বিঘা বা তারও কম।")}</p></div><p class="hint" style="margin:0 0 6px">${L2("Follow the chain. Tap a box to read more.", "ধাপগুলো অনুসরণ করো। বিস্তারিত পড়তে বাক্সে চাপ দাও।")}</p><div id="g4u-f"></div>`;
  flow($("#g4u-f", el), L2([
    ["The population keeps growing", "Bangladesh already has far more people than its small area can comfortably hold."],
    ["More homes, roads, mills and towns are needed", "Houses are built on land that used to grow crops."],
    ["Farmland shrinks", "There was already less cultivable land than the country needs; now it is falling further."],
    ["Land is divided again and again among heirs", "The plots become so small that scientific, modern farming is hard to do on them."],
    ["People fill canals and wetlands and clear forests", "The natural character and use of the land is changed to make room to live."],
    ["Risk of natural disaster", "If this goes on, a natural catastrophe becomes unavoidable. Land must be used in a planned way and the environment protected."]],
    [["জনসংখ্যা ক্রমাগত বাড়ছে", "আয়তনের তুলনায় বাংলাদেশের জনসংখ্যা এমনিতেই অনেক বেশি।"],
    ["বাড়িঘর, রাস্তা, কলকারখানা ও শহর বেশি লাগছে", "যে জমিতে ফসল হতো, সেখানে ঘরবাড়ি তৈরি হচ্ছে।"],
    ["চাষযোগ্য জমি কমে যাচ্ছে", "প্রয়োজনের তুলনায় আবাদি জমি আগে থেকেই কম; এখন তা আরও কমছে।"],
    ["উত্তরাধিকারীদের মধ্যে জমি বারবার ভাগ হচ্ছে", "জমি এত ছোট ছোট খণ্ড হয়ে যায় যে তাতে বৈজ্ঞানিক পদ্ধতিতে চাষ করা কঠিন।"],
    ["খাল-বিল ভরাট ও বনজঙ্গল কাটা হচ্ছে", "বসতির জায়গা করতে ভূমির স্বাভাবিক প্রকৃতি ও ব্যবহার বদলে ফেলা হচ্ছে।"],
    ["প্রাকৃতিক বিপর্যয়ের ঝুঁকি", "এভাবে চলতে থাকলে একসময় প্রাকৃতিক বিপর্যয় অনিবার্য। তাই ভূমির পরিকল্পিত ব্যবহার ও পরিবেশ সংরক্ষণ দরকার।"]]));
};

/* 4.2.1 three seasons, month by month, with the textbook's temperatures on the map */
const MON = () => L2(["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], ["জানু", "ফেব্রু", "মার্চ", "এপ্রি", "মে", "জুন", "জুলাই", "আগ", "সেপ্টে", "অক্টো", "নভে", "ডিসে"]);
const monthStrip = (rows) => `<div style="display:grid;gap:5px">${rows.map(([lab, cells]) => `<div>${lab ? `<div style="font-size:13.5px;color:var(--muted)">${lab}</div>` : ""}<div style="display:grid;grid-template-columns:repeat(12,1fr);gap:2px">${cells.map((c, i) => `<span style="background:${c || "var(--rule)"};border-radius:4px;height:26px;font-size:10.5px;display:grid;place-items:center;color:${c ? "#fff" : "var(--muted)"};overflow:hidden">${MON()[i]}</span>`).join("")}</div></div>`).join("")}</div>`;
const SEAS = { w: "#3f84c4", s: "#d9822b", r: "#3d9d6b", a: "#a07a3a" };
W.g4climate = (el) => {
  const bdS = "wwsssrrrrrww".split("").map(c => SEAS[c]);
  const S = {
    w: [L2("Winter: November to February", "শীতকাল: নভেম্বর থেকে ফেব্রুয়ারি"), L2(["The Sun is over the southern hemisphere, so its rays reach Bangladesh at a slant and bring less heat", "Highest about 29 °C, lowest about 11 °C", "January is the coldest month: average 17.7 °C", "It gets colder from the sea coast in the south towards the north", "Dry and comfortable; only a little rain"], ["সূর্য দক্ষিণ গোলার্ধে থাকে, তাই বাংলাদেশে রশ্মি তির্যকভাবে পড়ে; তাপ কম", "সর্বোচ্চ প্রায় ২৯ °সে, সর্বনিম্ন প্রায় ১১ °সে", "জানুয়ারি শীতলতম মাস: গড় তাপমাত্রা ১৭.৭ °সে", "দক্ষিণের সমুদ্র উপকূল থেকে উত্তর দিকে তাপমাত্রা ক্রমশ কমে", "শুষ্ক ও আরামদায়ক; বৃষ্টি খুব কম"]),
      [["chattogram", 20, "end"], ["noakhali", 19.4, "end"], ["dhaka", 18.3, "end"], ["bogura", 17.7], ["dinajpur", 16.6]], L2("Average temperature in January (°C): cooler towards the north", "জানুয়ারির গড় তাপমাত্রা (°সে): উত্তরে গেলে ঠান্ডা বেশি")],
    s: [L2("Summer: March to May", "গ্রীষ্মকাল: মার্চ থেকে মে"), L2(["The hottest season: highest about 38 °C, lowest about 21 °C", "April is the hottest month on average", "Sea breezes keep the south cooler, so it gets hotter from south to north", "Dry, cool air from the west and north-west meets the moist monsoon air: Kalbaishakhi storms", "In April and May depressions in the Bay of Bengal bring cyclones to the coast, such as the cyclone of 29 April 1991"], ["উষ্ণতম ঋতু: সর্বোচ্চ প্রায় ৩৮ °সে, সর্বনিম্ন প্রায় ২১ °সে", "গড় হিসাবে এপ্রিল উষ্ণতম মাস", "সামুদ্রিক বায়ুর প্রভাবে দক্ষিণ কিছুটা ঠান্ডা থাকে, তাই দক্ষিণ থেকে উত্তরে তাপমাত্রা বাড়ে", "পশ্চিম ও উত্তর-পশ্চিমের শুষ্ক, শীতল বায়ু আর্দ্র মৌসুমি বায়ুর সাথে মিলে কালবৈশাখী ঝড় ঘটায়", "এপ্রিল-মে মাসে বঙ্গোপসাগরের নিম্নচাপ থেকে উপকূলে ঘূর্ণিঝড় আঘাত করে; যেমন ১৯৯১ সালের ২৯ এপ্রিলের ঘূর্ণিঝড়"]),
      [["coxsbazar", 27.64, "end"], ["narayanganj", 28.66, "end"], ["rajshahi", 30]], L2("Average temperature in April (°C): hotter towards the north", "এপ্রিলের গড় তাপমাত্রা (°সে): উত্তরে গেলে গরম বেশি")],
    r: [L2("Rainy season: June to October", "বর্ষাকাল: জুন থেকে অক্টোবর"), L2(["Begins when the monsoon arrives at the end of June", "The Sun shines almost straight down, but the heavy rain keeps the heat from rising much", "Always warm: average about 27 °C; June and September feel hottest", "Four-fifths of the year's rain falls in this season", "Wide areas are flooded; too much rain and early floods can come"], ["জুন মাসের শেষ দিকে মৌসুমি বায়ু এলে বর্ষা শুরু হয়", "সূর্য প্রায় লম্বভাবে কিরণ দেয়, তবে প্রচুর বৃষ্টির কারণে তাপমাত্রা তেমন বাড়ে না", "আবহাওয়া সবসময় উষ্ণ: গড় প্রায় ২৭ °সে; জুন ও সেপ্টেম্বরে গরম বেশি", "বছরের মোট বৃষ্টির পাঁচ ভাগের চার ভাগ এই ঋতুতে হয়", "বিস্তীর্ণ এলাকা প্লাবিত হয়; অতিবৃষ্টি ও অকাল বন্যা দেখা দেয়"]), [], L2("In the rainy season the whole country is warm and wet. See the next lesson for the rainfall map.", "বর্ষাকালে সারা দেশ উষ্ণ ও আর্দ্র। বৃষ্টিপাতের মানচিত্র পরের পাঠে।")] };
  el.innerHTML = monthStrip([["", bdS]]) + `<div style="margin-top:8px">${chipHtml("g4c-s", [["w", L2("Winter", "শীত")], ["s", L2("Summer", "গ্রীষ্ম")], ["r", L2("Rainy season", "বর্ষা")]], "w")}</div><div class="g4c-map" style="margin-top:8px"></div><p class="hint" id="g4c-h" style="margin:6px 0"></p><div class="g-card" id="g4c-c"></div><div class="g-src">${SRC.bd()}</div>`;
  bdMap($(".g4c-map", el), { nbLabels: false, lines: true }).then(m => {
    const show = k => {
      const s = S[k]; m.paint(() => ({ fill: SEAS[k], op: .22 }));
      m.marks(s[2].map(([p, v, an]) => ({ place: p, label: `${L2(m.d.places[p].en, m.d.places[p].bn)} ${B(v)}°`, col: SEAS[k], r: 4.5, anchor: an || "start", dx: an ? -7 : 7 })));
      $("#g4c-h", el).textContent = s[3]; $("#g4c-c", el).innerHTML = card(s[0], list(s[1]));
    };
    chips(el, ".g4c-s", show); show("w");
  }).catch(() => {});
};

/* 4.2.2 how much rain, and where */
W.g4rain = (el) => {
  const D = { we: [L2("Rainy-season rain from west to east", "পশ্চিম থেকে পূর্বে বর্ষার বৃষ্টি"), [["pabna", 114], ["dhaka", 120], ["cumilla", 140], ["sreemangal", 180], ["rangamati", 190]], L2("Rain increases steadily from the west of the country to the east.", "দেশের পশ্চিম থেকে পূর্বদিকে বৃষ্টিপাত ক্রমেই বাড়ে।")],
    hc: [L2("Foothills and the coast", "পাহাড়ের পাদদেশ ও উপকূল"), [["sylhet", 340], ["coxsbazar", 320], ["rangamati", 280], ["chattogram", 250], ["patuakhali", 200]], L2("At the foot of the hills and along the coast, nowhere gets less than 200 cm. The hills of Sylhet get the most.", "পাহাড়ের পাদদেশ ও উপকূলবর্তী অঞ্চলে কোথাও ২০০ সেমির কম বৃষ্টি হয় না। সিলেটের পাহাড়ি অঞ্চলে সবচেয়ে বেশি।")] };
  el.innerHTML = chipHtml("g4r-m", [["we", D.we[0]], ["hc", D.hc[0]]], "we") + `<div class="g4r-map" style="margin-top:8px"></div><div id="g4r-b" style="margin-top:8px"></div><div class="g-card" id="g4r-c" style="margin-top:8px"></div><div class="g-src">${L2("Rainfall figures are the textbook's. The blue arrows only sketch the direction of the south-west monsoon. ", "বৃষ্টিপাতের সংখ্যাগুলো পাঠ্যবইয়ের। নীল তীরগুলো শুধু দক্ষিণ-পশ্চিম মৌসুমি বায়ুর দিক বোঝাতে আঁকা। ")}${SRC.bd()}</div>`;
  bdMap($(".g4r-map", el), { nbLabels: false }).then(m => {
    m.draw([[89.6, 20.9], [90.7, 20.8], [91.5, 20.95]].map(([lo, la]) => { const [x, y] = m.P(lo, la); return `<path d="M${x} ${y} l14 -30" stroke="var(--g-river)" stroke-width="2.4" fill="none"/><path d="M${x + 7} ${y - 26} l7 -4 l1 9" stroke="var(--g-river)" stroke-width="2.4" fill="none"/>`; }).join("") + `<text x="${m.X(89.2)}" y="${m.Y(20.68)}" font-size="12" fill="var(--g-river)" font-weight="600">${L2("moist south-west monsoon", "আর্দ্র দক্ষিণ-পশ্চিম মৌসুমি বায়ু")}</text>`, "wind");
    const show = k => {
      const [, rows, note] = D[k];
      m.marks(rows.map(([p, v]) => ({ place: p, label: `${L2(m.d.places[p].en, m.d.places[p].bn)} ${B(v)}`, r: 2 + Math.sqrt(v) / 2.6, col: "var(--g-river)", anchor: ["pabna", "dhaka", "patuakhali", "chattogram", "coxsbazar"].includes(p) ? "end" : "start", dx: ["pabna", "dhaka", "patuakhali", "chattogram", "coxsbazar"].includes(p) ? -10 : 10 })));
      $("#g4r-b", el).innerHTML = bars(rows.map(([p, v]) => [L2(m.d.places[p].en, m.d.places[p].bn) + (p === "sylhet" ? L2(" hills", "-এর পাহাড়") : ""), v, "var(--g-river)"]), 340, L2(" cm", " সেমি"));
      $("#g4r-c", el).innerHTML = `<p>${note}</p><p>${L2("Four-fifths of the year's rain falls in the rainy season: on average from 119 cm (least) to 340 cm (most).", "বছরের মোট বৃষ্টির পাঁচ ভাগের চার ভাগ বর্ষাকালে হয়: গড়ে সর্বনিম্ন ১১৯ সেমি থেকে সর্বোচ্চ ৩৪০ সেমি।")}</p>`;
    };
    chips(el, ".g4r-m", show); show("we");
  }).catch(() => {});
};

/* 4.2.3 four countries, four calendars of seasons */
